from pathlib import Path
import hashlib,sys
dest=Path(sys.argv[1]); assert dest.is_dir()
sources={}
sources["CASE313_O2.patch"]=("diff --git a/src/resources/extensions/gsd/prompts/complete-milestone.md b/src/resources/extensions/gsd/prompts/complete-milestone.md\nindex 91ac07e..ec036fc 100644\n--- a/src/resources/extensions/gsd/prompts/complete-milestone.md\n+++ b/src/resources/extensions/gsd/prompts/complete-milestone.md\n@@ -37,7 +37,7 @@ Then:\n \n **Success path** (all verifications passed — continue with steps 9–13):\n \n-9. **Persist completion through `gsd_complete_milestone`.** Call it with the parameters below. The tool updates the milestone status in the DB, renders `{{milestoneSummaryPath}}`, and validates all slices are complete before proceeding.\n+9. **Persist completion through `gsd_complete_milestone`.** Call it with **valid JSON tool arguments**, not YAML or Markdown bullet lists. The milestone summary template in the inlined context uses YAML lists for the *output file only*; do not copy that syntax into tool arguments. The tool updates the milestone status in the DB, renders `{{milestoneSummaryPath}}`, and validates all slices are complete before proceeding.\n \n    **Required parameters:**\n    - `milestoneId` (string) — Milestone ID (e.g. M001)\n@@ -52,6 +52,16 @@ Then:\n    - `lessonsLearned` (array of strings) — Lessons learned during the milestone\n    - `verificationPassed` (boolean) — Must be `true` — confirms that code change verification, success criteria, and definition of done checks all passed before completion\n \n+   **JSON array format (required for list fields):**\n+   ```json\n+   {\n+     \"keyDecisions\": [\"Use the existing notification API\", \"Keep state in the database\"],\n+     \"keyFiles\": [\"src/main.ts — Implemented notification handling\", \"src/state.ts — Persisted state\"],\n+     \"lessonsLearned\": [\"Verify the integration before completing the milestone\"]\n+   }\n+   ```\n+   These are example field values, **not a complete tool call**; include every required parameter listed above. Use `[]` if a list is empty. Never write `\"keyDecisions\": - decision` or `\"keyFiles\": - file` — a leading `-` is YAML list syntax, not valid JSON. Keep `followUps` and `deviations` as strings when provided.\n+\n    **Optional parameters:**\n    - `followUps` (string) — Follow-up items for future milestones\n    - `deviations` (string) — Deviations from the original plan\ndiff --git a/src/resources/extensions/gsd/templates/milestone-summary.md b/src/resources/extensions/gsd/templates/milestone-summary.md\nindex a361087..751496b 100644\n--- a/src/resources/extensions/gsd/templates/milestone-summary.md\n+++ b/src/resources/extensions/gsd/templates/milestone-summary.md\n@@ -1,4 +1,7 @@\n ---\n+# This is YAML frontmatter for the rendered summary file, NOT JSON tool arguments.\n+# When calling gsd_complete_milestone, pass keyDecisions, keyFiles, and\n+# lessonsLearned as JSON arrays of strings (e.g. [\"decision 1\", \"decision 2\"]).\n id: {{milestoneId}}\n provides:\n   - {{whatThisMilestoneProvides}}\ndiff --git a/src/resources/extensions/gsd/tests/complete-milestone.test.ts b/src/resources/extensions/gsd/tests/complete-milestone.test.ts\nindex 78211dc..8232fcc 100644\n--- a/src/resources/extensions/gsd/tests/complete-milestone.test.ts\n+++ b/src/resources/extensions/gsd/tests/complete-milestone.test.ts\n@@ -150,6 +150,18 @@ describe(\"complete-milestone\", () => {\n     );\n   });\n \n+  test(\"completion prompt distinguishes JSON tool arrays from summary YAML lists\", () => {\n+    const prompt = loadPromptFromWorktree(\"complete-milestone\");\n+    const summaryTemplate = readFileSync(join(__dirname, \"..\", \"templates\", \"milestone-summary.md\"), \"utf-8\");\n+\n+    assert.ok(prompt.includes('\"keyDecisions\": ['), \"prompt demonstrates JSON arrays for decisions\");\n+    assert.ok(prompt.includes('\"keyFiles\": ['), \"prompt demonstrates JSON arrays for files\");\n+    assert.ok(prompt.includes('\"lessonsLearned\": ['), \"prompt demonstrates JSON arrays for lessons\");\n+    assert.ok(prompt.includes('Use `[]` if a list is empty'), \"prompt handles empty arrays\");\n+    assert.ok(prompt.includes('Keep `followUps` and `deviations` as strings'), \"prompt matches optional tool parameter types\");\n+    assert.ok(summaryTemplate.includes('NOT JSON tool arguments'), \"YAML template explicitly distinguishes output from tool arguments\");\n+  });\n+\n   test(\"handleCompleteMilestone rejects when verificationPassed is false\", async () => {\n     const { handleCompleteMilestone } = await import(\"../tools/complete-milestone.ts\");\n     const base = createFixtureBase();\n","bb4db2b111f0d71e66d890f605b0cdc68ec7ac0a9276792845204407bbb24a53",4461)
sources["CASE313_O3.patch"]=("diff --git a/src/resources/extensions/gsd/prompts/complete-milestone.md b/src/resources/extensions/gsd/prompts/complete-milestone.md\nindex 91ac07e..d13de19 100644\n--- a/src/resources/extensions/gsd/prompts/complete-milestone.md\n+++ b/src/resources/extensions/gsd/prompts/complete-milestone.md\n@@ -39,6 +39,18 @@ Then:\n \n 9. **Persist completion through `gsd_complete_milestone`.** Call it with the parameters below. The tool updates the milestone status in the DB, renders `{{milestoneSummaryPath}}`, and validates all slices are complete before proceeding.\n \n+   **JSON tool-call format (not YAML or Markdown):** Pass a JSON object to the tool. In particular, `keyDecisions`, `keyFiles`, and `lessonsLearned` MUST be JSON arrays of strings, enclosed in `[]` with each item quoted. Do not copy the `- {{decision}}` YAML list syntax from the milestone-summary output template into tool arguments. Use `[]` when there are no entries. For example, the array fields in the tool arguments should look like:\n+\n+   ```json\n+   {\n+     \"keyDecisions\": [\"Use the existing notification API\", \"Keep the state in the database\"],\n+     \"keyFiles\": [\"src/notifications.ts — Added notification handling\"],\n+     \"lessonsLearned\": [\"Verify the integration before closing the milestone\"]\n+   }\n+   ```\n+\n+   These are example fields within the full tool-call object; include all required parameters below. `followUps` and `deviations` are optional **strings**, not arrays.\n+\n    **Required parameters:**\n    - `milestoneId` (string) — Milestone ID (e.g. M001)\n    - `title` (string) — Milestone title\ndiff --git a/src/resources/extensions/gsd/templates/milestone-summary.md b/src/resources/extensions/gsd/templates/milestone-summary.md\nindex a361087..088ee9c 100644\n--- a/src/resources/extensions/gsd/templates/milestone-summary.md\n+++ b/src/resources/extensions/gsd/templates/milestone-summary.md\n@@ -1,3 +1,7 @@\n+<!-- This template describes the generated Markdown/YAML milestone summary, NOT the\n+     JSON arguments for gsd_complete_milestone. In the tool call, keyDecisions,\n+     keyFiles, and lessonsLearned must be JSON arrays of strings (e.g. [\"item\"]),\n+     never YAML bullet lists. -->\n ---\n id: {{milestoneId}}\n provides:\ndiff --git a/src/resources/extensions/gsd/tests/complete-milestone.test.ts b/src/resources/extensions/gsd/tests/complete-milestone.test.ts\nindex 78211dc..b0beca4 100644\n--- a/src/resources/extensions/gsd/tests/complete-milestone.test.ts\n+++ b/src/resources/extensions/gsd/tests/complete-milestone.test.ts\n@@ -150,6 +150,24 @@ describe(\"complete-milestone\", () => {\n     );\n   });\n \n+  test(\"completion prompt distinguishes JSON tool arrays from YAML summary lists\", () => {\n+    const prompt = loadPromptFromWorktree(\"complete-milestone\");\n+    const summaryTemplate = readFileSync(join(__dirname, \"..\", \"templates\", \"milestone-summary.md\"), \"utf-8\");\n+\n+    assert.match(prompt, /`keyDecisions`, `keyFiles`, and `lessonsLearned` MUST be JSON arrays of strings/);\n+    assert.match(prompt, /Use `\\[\\]` when there are no entries/);\n+    assert.match(prompt, /`followUps` and `deviations` are optional \\*\\*strings\\*\\*/);\n+    const example = prompt.match(/```json\\s*(\\{[\\s\\S]*?\\})\\s*```/);\n+    assert.ok(example, \"prompt includes JSON argument example\");\n+    const args = JSON.parse(example[1]);\n+    for (const key of [\"keyDecisions\", \"keyFiles\", \"lessonsLearned\"]) {\n+      assert.ok(Array.isArray(args[key]), `${key} is a JSON array`);\n+      assert.ok(args[key].every((item: unknown) => typeof item === \"string\"), `${key} contains strings`);\n+    }\n+    assert.match(summaryTemplate, /NOT the\\s+JSON arguments for gsd_complete_milestone/);\n+    assert.match(summaryTemplate, /key_decisions:\\s*\\n  - \\{\\{decision\\}\\}/);\n+  });\n+\n   test(\"handleCompleteMilestone rejects when verificationPassed is false\", async () => {\n     const { handleCompleteMilestone } = await import(\"../tools/complete-milestone.ts\");\n     const base = createFixtureBase();\n","c08291cc4d105708cbd468e5ba119de3341c4eb2bcd2f59b32b383c35a151c0b",3974)
for name,(content,expected,size) in sources.items():
    data=content.encode('utf-8')
    assert len(data)==size,(name,len(data),size)
    assert hashlib.sha256(data).hexdigest()==expected,('sha mismatch',name)
    dst=dest/name
    with dst.open('xb') as f:f.write(data)
print('STAGED_PATCHES',','.join(sources))
